/**
 * In-browser data store for demo mode.
 *
 * The catalogue (salons, menus, reviews) is a snapshot of the real API
 * (fixtures.json, regenerated by scripts/export-fixtures.mjs). Anything a visitor
 * creates — accounts, bookings, reviews, messages — lives only in this browser's
 * localStorage and never reaches a server.
 */
import fixtures from './fixtures.json';

const STORAGE_KEY = 'bms.demo.v1';
/** Bump when the generated sample activity changes, so stored demo data is rebuilt. */
const DATA_REV = 'r2';

