/** Small deterministic PRNG so every visitor sees the same sample history. */
const mulberry32 = (seed) => () => {
  let t = (seed += 0x6d2b79f5);
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

const pad = (n) => String(n).padStart(2, '0');
export const localIso = (d) =>
  `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:00`;

const at = (dayOffset, hour, minute = 0) => {
  const d = new Date();
  d.setDate(d.getDate() + dayOffset);
  d.setHours(hour, minute, 0, 0);
  return d;
};

/** A lived-in starting point so demo pages aren't empty: a few bookings and one chat. */
const sampleActivity = (salons, services) => {
  const pick = (salonId, n) => services.filter((s) => s.salonId === salonId).slice(0, n);
  const ownerSalon = salons.find((s) => s.ownerId === 2) || salons[0];
  const other = salons.find((s) => s.ownerId !== 2) || salons[1];
  const plan = [
    { salon: other, day: 2, hour: 11, status: 'CONFIRMED', n: 1 },
    { salon: ownerSalon, day: 3, hour: 16, status: 'PENDING', n: 2 },
    { salon: ownerSalon, day: -9, hour: 12, status: 'COMPLETED', n: 1 },
    { salon: other, day: -24, hour: 18, status: 'CANCELLED', n: 1 },
  ];
  const bookings = plan.map((p, i) => {
    const items = pick(p.salon.id, p.n);
    const minutes = items.reduce((m, s) => m + (s.duration || 30), 0) || 30;
    const start = at(p.day, p.hour);
    return {
      id: 5001 + i,
      salonId: p.salon.id,
      customerId: 1,
      startTime: localIso(start),
      endTime: localIso(new Date(start.getTime() + minutes * 60000)),
      serviceOfferingIds: items.map((s) => s.id),
      status: p.status,
      totalPrice: items.reduce((sum, s) => sum + s.price, 0),
      createdAt: localIso(at(p.day - 3, 10)),
    };
  });
  const conversation = { id: 7001, customerId: 1, salonOwnerId: ownerSalon.ownerId, createdAt: localIso(at(-2, 10)) };
  const messages = [
    { id: 8001, conversationId: 7001, senderId: 1, receiverId: ownerSalon.ownerId, content: 'Hi! Is there parking near the salon?', status: 'READ', createdAt: localIso(at(-2, 10, 4)) },
    { id: 8002, conversationId: 7001, senderId: ownerSalon.ownerId, receiverId: 1, content: 'Yes — there’s paid parking right behind the building. See you soon!', status: 'DELIVERED', createdAt: localIso(at(-2, 10, 21)) },
  ];
  const notifications = [
    { id: 9001, type: 'BOOKING_CONFIRMATION', description: `Booking #5001 has been confirmed`, wasRead: false, userId: 1, bookingId: 5001, createdAt: localIso(at(-1, 9)) },
  ];
  return { bookings: [...bookings, ...sampleHistory(salons, services, bookings)], conversations: [conversation], messages, notifications };
};

/** ~90 days of bookings across all salons so dashboards and charts aren't empty. */
const sampleHistory = (salons, services, existing) => {
  const rand = mulberry32(20261011);
  const pickOne = (list) => list[Math.floor(rand() * list.length)];
  const taken = [...existing];
  const out = [];
  const ownerSalon = salons.find((s) => s.ownerId === 2);
  for (let i = 0; out.length < 140 && i < 600; i++) {
    // The demo owner's salon gets a steady share so their workspace has real work in it.
    const salon = ownerSalon && rand() < 0.22 ? ownerSalon : pickOne(salons);
    const menu = services.filter((s) => s.salonId === salon.id);
    if (!menu.length) continue;
    const items = [pickOne(menu)];
    if (rand() < 0.3) {
      const extra = pickOne(menu);
      if (extra.id !== items[0].id) items.push(extra);
    }
    const day = Math.floor(rand() * 98) - 85;
    const [oh, om] = salon.openTime.split(':').map(Number);
    const [ch] = salon.closeTime.split(':').map(Number);
    const minutes = items.reduce((m, s) => m + (s.duration || 30), 0);
    const hour = oh + Math.floor(rand() * Math.max(1, ch - oh - Math.ceil(minutes / 60)));
    const start = at(day, hour, rand() < 0.5 ? 0 : 30);
    if (start.getHours() * 60 + start.getMinutes() < oh * 60 + om) continue;
    const end = new Date(start.getTime() + minutes * 60000);
    if (taken.some((b) => b.salonId === salon.id && new Date(b.startTime) < end && new Date(b.endTime) > start)) continue;
    const future = start > new Date();
    const roll = rand();
    const status = future ? (roll < 0.6 ? 'CONFIRMED' : 'PENDING') : roll < 0.82 ? 'COMPLETED' : 'CANCELLED';
    const booking = {
      id: 6001 + out.length,
      salonId: salon.id,
      customerId: SAMPLE_CUSTOMERS[Math.floor(rand() * SAMPLE_CUSTOMERS.length)].id,
      startTime: localIso(start),
      endTime: localIso(end),
      serviceOfferingIds: items.map((s) => s.id),
      status,
      totalPrice: items.reduce((sum, s) => sum + s.price, 0),
      createdAt: localIso(at(Math.min(day, 0) - 1 - Math.floor(rand() * 6), 9 + Math.floor(rand() * 9))),
    };
    taken.push(booking);
    out.push(booking);
  }
  return out;
};

const fresh = () => {
  const activity = sampleActivity(fixtures.salons, fixtures.services);
  return {
    version: `${fixtures.version}-${DATA_REV}`,
    users: [...DEMO_USERS.map((u) => ({ ...u, passwordHash: null })), ...SAMPLE_CUSTOMERS],
    sessions: {},
    salons: fixtures.salons,
    services: fixtures.services,
    categories: fixtures.categories,
    reviews: fixtures.reviews,
    ...activity,
    seq: 20000,
  };
};

const load = () => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed.version === `${fixtures.version}-${DATA_REV}`) return parsed;
    }
  } catch {
    /* corrupted or unavailable storage → start fresh */
  }
  return fresh();
};

export const db = load();

export const save = () => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(db));
  } catch {
    /* quota or private mode: demo keeps working in memory */
  }
};

export const nextId = () => {
  db.seq += 1;
  return db.seq;
};

export const nowIso = () => localIso(new Date());

/** Wipes everything this browser created in demo mode. */
export const resetDemoData = () => {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {
    /* ignore */
  }
};
